    public static void LvliActualDamageNumericChoicesAndTurnBudgetsCold()
    {
        {
            var(g,r)=Start("base");Need(V(g).Hp==9&&V(g).MaxHp==9,"The classic identity fixture really uses the custom body's8HP plus native Lord bonus.");var before=V(g).HandCount;Use(g,"deal-two",[1]);Activate(g,Lvli);Reach(g,()=>Current(g)is{Stage:WenYangStage.Choice});
            var prompt=P(g)!;var state=State(g);Need(prompt.IsPrivate&&g.CreateSnapshot(1).PendingDecision is null&&!g.Submit(new AnswerPromptCommand(1,prompt.PromptId,prompt.Choices[0].Id,g.Revision)).Accepted&&State(g)==state,"The genuine damaged-use Lvli choice belongs only to its owner; another seat cannot answer or inspect it.");
            g=Cold(g,r);Branch(g,"draw");Play(g);var issued=E<WenYangLvliIssuedEvent>(g).Single();Need(issued.Requested==V(g).Hp-before&&V(g).HandCount==V(g).Hp&&E<WenYangDrawIssuedEvent>(g).Single().Actual==issued.Requested&&E<DamageAppliedEvent>(g).Any(e=>e.TargetSeat==1&&e.Amount==2),"Two actual damage points create one per-damage Lvli activation, drawing its frozen numeric difference through native DrawCards.");
            Use(g,"deal-one",[1]);Play(g);Need(E<WenYangLvliIssuedEvent>(g).Length==1,"Unawakened Lvli has one shared quota in the actual turn, including later damage instances.");_=Cold(g,r);
        }
        {
            var(g,r)=Start("equal");Need(V(g).HandCount==V(g).Hp,"The equal-values fixture starts with real equal hand and HP.");Use(g,"deal-one",[1]);Activate(g,Lvli);Branch(g,"recover");Play(g);
            Need(E<WenYangLvliIssuedEvent>(g)is[{Requested:0,ExpectedRecovery:0}]&&E<RecoveryAppliedEvent>(g).Length==0,"Equal hand/HP still permits real activation and either no-effect branch, consuming the actual-turn use.");_=Cold(g,r);
        }
        {
            var(g,r)=Start("recover");Use(g,"lose-four");Play(g);Use(g,"draw-four");Play(g);var hp=V(g).Hp;Use(g,"deal-one",[1]);Activate(g,Lvli);Branch(g,"recover");Reach(g,()=>P(g)?.SkillPrompt?.SkillId==Health);var issued=E<WenYangLvliIssuedEvent>(g).Single();
            Need(issued.Requested==10-hp&&issued.ExpectedRecovery==V(g).MaxHp-hp&&V(g).Hp==V(g).MaxHp&&Current(g)?.Stage==WenYangStage.RecoveryChildren,"The frozen hand-to-HP request remains five while the native recovery cap applies four and exposes a real recovery child.");g=Cold(g,r);Continue(g);Play(g);Need(E<RecoveryAppliedEvent>(g).Single().Amount==issued.ExpectedRecovery&&E<WenYangCompletedEvent>(g).Count(e=>e.Op==SkillProgramEffectOp.ResolveLvliActualDamageChoice)==1,"Native recovery and the exact original damage parent return once after cold restore.");
        }
    }
    public static void BothAwakeningsActualBoundariesAndSharedDamageQuotaCold()
    {
