            Need(E<WenYangAwakenedEvent>(g).Select(e=>e.Level).SequenceEqual([1,2])&&V(g).MaxHp==7&&Has(g,Qingjiao)&&E<WenYangLeafGrantedEvent>(g).Select(e=>e.SkillId).SequenceEqual([Beishui,Qingjiao]),"The genuine next Preparation with empty hand awakens Beishui once, lowers maximum HP again and grants Qingjiao.");Skip(g);Play(g);
            Use(g,"source-less");Activate(g,Lvli);Branch(g,"draw");Play(g);Use(g,"deal-one",[1]);Activate(g,Lvli);Branch(g,"recover");Play(g);var turn=g.State.TurnNumber;
            Need(E<WenYangLvliIssuedEvent>(g).Count(e=>e.ActualTurn==turn)==2&&E<DamageAppliedEvent>(g).Any(e=>e.TargetSeat==0&&e.SourceLess),"After both actual awakenings, source-less received damage and caused damage share exactly two own-turn uses.");Use(g,"self-damage");Play(g);Need(E<WenYangLvliIssuedEvent>(g).Count(e=>e.ActualTurn==turn)==2,"Self damage does not double-offer caused/received entries or evade the same actual-turn budget.");
            Use(g,"draw-four");Play(g);End(g);Reach(g,()=>Offer(g,Lvli));var foreignTurn=g.State.TurnNumber;var foreignOwner=g.State.CurrentSeat;var hurtAtOffer=E<DamageAppliedEvent>(g).Count(e=>e.SourceSeat==foreignOwner&&e.TargetSeat==0);Activate(g,Lvli);Branch(g,"draw");Reach(g,()=>E<DamageAppliedEvent>(g).Count(e=>e.SourceSeat==foreignOwner&&e.TargetSeat==0)>hurtAtOffer);
            Need(E<WenYangLvliIssuedEvent>(g).Count(e=>e.ActualTurn==foreignTurn)==1&&foreignOwner!=0,"The same fully awakened owner still has one shared use in another character's actual turn, despite two separate real incoming damage instances.");g=Cold(g,r);
            Play(g);var aoeTurn=g.State.TurnNumber;NativeBarbarian(g);Activate(g,Lvli);Branch(g,"recover");Activate(g,Lvli);Branch(g,"draw");Play(g);var aoe=E<WenYangLvliIssuedEvent>(g).Where(e=>e.ActualTurn==aoeTurn).ToArray();
            var group=E<GroupCardUsedEvent>(g).Single(e=>e.SourceSeat==0&&e.CardKind==CardKind.BarbarianAssault);var windows=E<DamageTriggerWindowOpenedEvent>(g).Where(e=>aoe.Any(a=>a.DamageWindowId==e.ResolutionId)).ToArray();
            Need(aoe.Length==2&&aoe.Select(e=>e.DamageWindowId).Distinct().Count()==2&&windows.Length==2&&windows.Select(w=>w.TargetSeat).Distinct().Count()==2&&windows.All(w=>w.SourceSeat==0&&w.CardId==group.CardId&&w.CardKind==CardKind.BarbarianAssault&&group.TargetSeats.Contains(w.TargetSeat)&&aoe.Count(a=>a.DamageWindowId==w.ResolutionId&&a.DamageId==w.DamageFrameId)==1),"Two actual AOE recipient damage windows from the same physical native Group Use each permit one awakened activation, with exact window-to-damage-frame invoices. "+JsonSerializer.Serialize(new{aoe,group,windows}));_=Cold(g,r);
        }
        {
            var(g,r)=Start("hand-high");Use(g,"draw-four");Play(g);var hand=V(g).HandCount;var hp=V(g).Hp;Need(hand-hp>=3,"The opposite sign of the absolute awakening threshold is real.");End(g);Reach(g,()=>E<WenYangAwakenedEvent>(g).Any(e=>e.Level==1));Need(E<WenYangAwakenedEvent>(g).Count(e=>e.Level==1)==1,"Hand above HP by three also awakens; this is an absolute difference, not a one-sided comparison.");_=Cold(g,r);
        }
        {
            var(g,r)=Start("foreign-awake");Need(V(g).Hp==V(g).HandCount,"The real own Ending initially fails the awakening threshold.");End(g);Reach(g,()=>Has(g,Beishui));var issued=E<WenYangStartedEvent>(g).Single(e=>e.Op==SkillProgramEffectOp.ResolveWenYangAwakening);Need(issued.TurnOwner!=0&&E<TurnEndedEvent>(g).Any(e=>e.ActorSeat==issued.TurnOwner&&e.TurnNumber==issued.ActualTurn),"The threshold reached by genuine incoming foreign-turn damage awakens only after that precise frozen foreign actual TurnEnded.");_=Cold(g,r);
        }
        {
            var(g,r)=Start("maximum-zero");Need(P(g)?.SkillPrompt?.SkillId==Death&&!V(g).IsAlive&&V(g).MaxHp==0&&E<WenYangAwakenedEvent>(g)is[{MaximumBefore:1,MaximumAfter:0}],"The new awakening operation truly pays the last maximum HP at the first actual TurnEnded and enters native death before this non-Lord owner's first Play.");g=Cold(g,r);Answer(g,c=>c.Targets.Count==1);Reach(g,()=>E<WenYangCompletedEvent>(g).Any(e=>e.Op==SkillProgramEffectOp.ResolveWenYangAwakening));Need(!Has(g,Beishui)&&E<PlayerDiedEvent>(g).Count(e=>e.VictimSeat==0)==1,"A dead owner gets no later linked grant, and the real death child returns to the paid awakening once.");
        }
    }
    public static void QingjiaoPhysicalInventorySubtypeScarcityAndIssuedEndingCold()
    {
        {
            var(g,r)=Start("qingjiao");var originals=V(g).Hand.Select(c=>c.Id).ToArray();Activate(g,Qingjiao);Reach(g,()=>P(g)?.SkillPrompt?.SkillId==Watch);var frame=g.ResolutionStack.OfType<ProgramSkillFrame>().Single(f=>f.WenYang is not null).Id;Need(originals.All(id=>g.CardMovements.Any(m=>m.CardId==id&&m.From==CardLocation.Hand(0)&&m.To==CardLocation.DiscardPile&&m.Reason.Value=="skill-program.wen-yang.qingjiao.hand-discard")),"All initial hand entities are paid together before Qingjiao obtains anything.");g=Cold(g,r);Continue(g);Play(g);
            var got=E<WenYangEntityMovedEvent>(g).Where(e=>e.FrameId==frame&&e.Step==2).ToArray();Need(got.Length==8&&got.Select(e=>e.Kind).Distinct().Count()==8&&got.Where(e=>EquipmentCatalog.IsEquipment(e.Kind)).Select(e=>EquipmentCatalog.Get(e.Kind).Slot).Distinct().Count()==got.Count(e=>EquipmentCatalog.IsEquipment(e.Kind))&&got.All(e=>e.From.Zone is CardZoneKind.DrawPile or CardZoneKind.DiscardPile)&&got.All(e=>e.To==CardLocation.Hand(0)),"Eight real deck/discard entities have different exact names and equipment slots; non-equipment cards remain independent candidates.");
            Need(E<NativeLogicalDiscardInvocationRecordedEvent>(g).Any(e=>e.Reason.Value=="skill-program.wen-yang.qingjiao.hand-discard"&&e.ActualCount==originals.Length)&&E<NativeDrawInvocationRecordedEvent>(g).All(e=>!e.Reason.Value.Contains("qingjiao",StringComparison.Ordinal)),"Qingjiao has one genuine logical hand discard and direct physical obtain, never eight substitute draws.");Use(g,"lose-qingjiao");Play(g);Need(!Has(g,Qingjiao),"The real source is lost before its already-issued Ending.");End(g);Reach(g,()=>E<WenYangQingjiaoDebtConsumedEvent>(g).Length==1&&E<WenYangCompletedEvent>(g).Any(e=>e.Op==SkillProgramEffectOp.ResolveQingjiaoIssuedEndingDiscard));Need(V(g).HandCount==0&&E<WenYangMovementIssuedEvent>(g).Count(e=>e.Stage==WenYangStage.EndingChildren)==1,"Issued Qingjiao debt survives genuine skill loss and pays its actual Ending HE once.");_=Cold(g,r);
        }
        {
            var(g,r)=Start("scarce-zero");Skip(g);Play(g);Use(g,"store",cards:[V(g).Hand.Single().Id]);Play(g);Need(V(g).HandCount==0,"The sole physical deck entity is genuinely stored outside deck/discard before the next Play.");End(g);Reach(g,()=>Offer(g,Qingjiao));Activate(g,Qingjiao);Play(g);Need(E<WenYangQingjiaoDebtIssuedEvent>(g)is[{Gained:0}]&&E<WenYangMovementIssuedEvent>(g).Where(e=>e.Stage is WenYangStage.HandDiscardChildren or WenYangStage.GainChildren).All(e=>e.Count==0),"Empty hand and exhausted combined inventory still complete the textual discard/obtain attempt with no invented cards or shuffle.");g=Cold(g,r);End(g);Reach(g,()=>E<WenYangQingjiaoDebtConsumedEvent>(g).Length==1);Need(E<WenYangMovementIssuedEvent>(g).Single(e=>e.Stage==WenYangStage.EndingChildren).Count==0,"A zero-card obtain attempt still issues and consumes one genuine Ending obligation.");
        }
    }
    public static void PaidChildrenSourceLossDeathAndNativeLionOxEndingCold()
    {
        foreach(var scene in new[]{"paid-loss","paid-death"})
        {
            var(g,r)=Start(scene);Activate(g,Qingjiao);Reach(g,()=>P(g)?.SkillPrompt?.SkillId==Watch);var id=g.ResolutionStack.OfType<ProgramSkillFrame>().Single(f=>f.WenYang is not null).Id;g=Cold(g,r);Continue(g);Reach(g,()=>E<WenYangCompletedEvent>(g).Any(e=>e.FrameId==id));
            Need(E<WenYangMovementIssuedEvent>(g).Count(e=>e.FrameId==id&&e.Stage==WenYangStage.HandDiscardChildren)==1&&E<WenYangCompletedEvent>(g).Count(e=>e.FrameId==id)==1,"Native paid-discard children never repeat the original whole-hand payment after source loss or death.");
            if(scene=="paid-loss"){Play(g);Need(!Has(g,Qingjiao)&&E<WenYangQingjiaoDebtIssuedEvent>(g).Single().Gained==8,"The truly lost conditional source does not cancel an already-paid obtain.");End(g);Reach(g,()=>E<WenYangQingjiaoDebtConsumedEvent>(g).Length==1);}
            else Need(!V(g).IsAlive&&E<PlayerDyingEvent>(g).Any(e=>e.VictimSeat==0)&&E<WenYangQingjiaoDebtIssuedEvent>(g).Length==0,"Real fatal payment children finish native rescue/death; no later card gain or Ending debt is fabricated for the dead recipient.");_=Cold(g,r);
        }
        {
            var(g,r)=Start("equipment");Activate(g,Qingjiao);Play(g);var lion=V(g).Hand.Single(c=>c.Kind==CardKind.SilverLion).Id;var ox=V(g).Hand.Single(c=>c.Kind==CardKind.WoodenOx).Id;Use(g,"place",[0],[lion]);Play(g);Use(g,"place",[0],[ox]);Play(g);var grain=V(g).Hand.Single().Id;Accept(g,new UseEquipmentEffectCommand(0,CardKind.WoodenOx,[grain],[],g.Revision,P(g)!.PromptId));Play(g);Use(g,"lose-one");Play(g);var hp=V(g).Hp;End(g);Reach(g,()=>P(g)?.SkillPrompt?.SkillId==Health);
            Need(Current(g)is{Stage:WenYangStage.EndingChildren}&&V(g).Equipment.Count==0&&V(g).WoodenOxGrainCount==0&&V(g).Hp==hp+1&&g.CardMovements.Any(m=>m.CardId==grain&&m.Reason==CardMoveReasons.WoodenOxGrainDiscard),"Qingjiao's actual Ending removes real Lion/Ox together, spills its actual hidden grain, and pauses in the native Lion recovery child.");g=Cold(g,r);Continue(g);Reach(g,()=>E<WenYangCompletedEvent>(g).Any(e=>e.Op==SkillProgramEffectOp.ResolveQingjiaoIssuedEndingDiscard));Need(E<WenYangEntityMovedEvent>(g).Count(e=>e.CardId==lion&&e.From==CardLocation.Equipment(0))==1&&E<RecoveryAppliedEvent>(g).Count(e=>e.TargetSeat==0)==1&&E<NativeLogicalDiscardInvocationRecordedEvent>(g).Any(e=>e.Reason.Value=="skill-program.wen-yang.qingjiao.ending-discard"&&e.ActualCount==2),"The exact issued Ending returns once, counting only the primary equipment cost while preserving native Lion/Ox secondary effects.");
        }
    }
    private static PlayerSnapshot V(GameEngine g,int seat=0)=>g.CreateSnapshot(seat).Players[seat];
    private static PendingDecision? P(GameEngine g)=>Enumerable.Range(0,4).Select(s=>g.CreateSnapshot(s).PendingDecision).FirstOrDefault(p=>p is not null);
    private static T[] E<T>(GameEngine g)where T:IGameEvent=>g.Events.Select(e=>e.Payload).OfType<T>().ToArray();
    private static bool Has(GameEngine g,string skill)=>V(g).Skills!.Any(s=>s.ContentId==skill);
    private static WenYangReceipt? Current(GameEngine g)=>g.ResolutionStack.OfType<ProgramSkillFrame>().LastOrDefault(f=>f.WenYang is not null)?.WenYang;
    private static bool Offer(GameEngine g,string skill)=>P(g)is{PlayerSeat:0}p&&p.SkillPrompt?.SkillId==skill&&p.Choices.Any(c=>c.Parameters.GetValueOrDefault("program-action")=="activate");
    private static void Need(bool yes,string message){if(!yes)throw new InvalidOperationException(message);}
    private static void Accept(GameEngine g,GameCommand c){var r=g.Submit(CommandJson.Deserialize(CommandJson.Serialize([c])).Single());Need(r.Accepted,r.Error?.Message??"Rejected genuine Wen Yang command.");}
    private static void Answer(GameEngine g,Func<PromptChoice,bool> choose){var p=P(g)!;Need(V(g,p.PlayerSeat).IsHuman,"AI decisions must use AdvanceOneStep.");var c=p.Choices.FirstOrDefault(choose);Need(c is not null,"Missing Wen Yang choice: "+Diagnostic(g));Accept(g,new AnswerPromptCommand(p.PlayerSeat,p.PromptId,c!.Id,g.Revision));}
    private static void Activate(GameEngine g,string skill){Reach(g,()=>Offer(g,skill));Answer(g,c=>c.Parameters.GetValueOrDefault("program-action")=="activate");}
    private static void Branch(GameEngine g,string branch){Reach(g,()=>Current(g)is{Stage:WenYangStage.Choice});Answer(g,c=>c.Parameters.GetValueOrDefault("branch")==branch);}
    private static void Skip(GameEngine g)=>Answer(g,c=>c.Parameters.GetValueOrDefault("program-action")=="skip");
    private static void Continue(GameEngine g)=>Answer(g,c=>c.Parameters.GetValueOrDefault("option-id")=="continue");
    private static void Use(GameEngine g,string id,int[]? targets=null,int[]? cards=null)=>Accept(g,new UseProgramSkillCommand(0,Driver,id,cards??[],targets??[],g.Revision,P(g)!.PromptId));
    private static void NativeBarbarian(GameEngine g){var a=g.GetHumanLegalActions().First(a=>a.PlayedCardKind==CardKind.BarbarianAssault);Accept(g,new PlayCardCommand(0,a.CardId!.Value,a.TargetSeats,g.Revision,P(g)!.PromptId,a.PlayedCardKind,a.TargetCardId){ConversionSource=a.ConversionSource});}
    private static void End(GameEngine g)=>Accept(g,new EndPlayPhaseCommand(0,g.Revision,P(g)!.PromptId));
    private static void Play(GameEngine g)=>Reach(g,()=>P(g)is{PlayerSeat:0,Kind:DecisionKind.PlayCard});
    private static string Diagnostic(GameEngine g)=>JsonSerializer.Serialize(new{g.State.TurnNumber,g.State.CurrentSeat,g.State.Winner,g.State.Phase,Hp=V(g).Hp,Hand=V(g).HandCount,Stage=Current(g)?.Stage,Prompt=P(g)is{}p?new{p.Kind,p.PlayerSeat,Skill=p.SkillPrompt?.SkillId,Choices=p.Choices.Take(3).Select(c=>c.Parameters)}:null,Awake=E<WenYangAwakenedEvent>(g),Tail=g.Events.TakeLast(5).Select(e=>e.Payload.ToString())});
    private static void Reach(GameEngine g,Func<bool> done)
    {
        for(var i=0;i<300;i++){if(done())return;Need(g.State.Winner==Winner.None,"Missing native Wen Yang boundary: "+Diagnostic(g));var p=P(g);if(p is null||!V(g,p.PlayerSeat).IsHuman)Accept(g,new AdvanceOneStepCommand(g.Revision));else if(p.Kind==DecisionKind.PlayCard)End(g);else if(p.Kind is DecisionKind.RespondDodge or DecisionKind.RespondSlash or DecisionKind.Nullification)Answer(g,c=>c.Cards.Count==0);else if(p.Kind==DecisionKind.RescueDying)Answer(g,c=>c.Parameters.GetValueOrDefault("response")=="let-die");else if(p.Choices.Any(c=>c.Parameters.GetValueOrDefault("program-action")=="skip"))Skip(g);else if(p.Choices.Any(c=>c.Parameters.GetValueOrDefault("option-id")=="continue"))Continue(g);else throw new InvalidOperationException("Unexpected Wen Yang prompt: "+Diagnostic(g));}throw new InvalidOperationException("Missing bounded Wen Yang boundary: "+Diagnostic(g));
    }
    private static string State(GameEngine g)=>JsonSerializer.Serialize(Enumerable.Range(0,4).Select(s=>g.CreateSnapshot(s)))+JsonSerializer.Serialize(g.ResolutionStack)+JsonSerializer.Serialize(g.CardMovements)+g.Events.Count;
    private static GameEngine Cold(GameEngine g,ContentRegistry r){var restored=GameReplay.Restore(GameCheckpointJson.Deserialize(GameCheckpointJson.Serialize(g.CreateCheckpoint())),r);Need(State(g)==State(restored),"Cold replay preserves exact native parent, damage quota, frozen numeric request, physical inventory and paid Ending without repeating costs.");return restored;}
    private static(GameEngine,ContentRegistry)Start(string scene)
    {
        var r=ContentRegistry.Build(new StandardContentPackage(),new Fixture(scene));var g=GameEngine.CreateStandard(new GameOptions{Seed=7,PlayerCount=4,HumanSeat=0,HumanRole=scene is"maximum-zero"or"paid-death"?Role.Renegade:Role.Lord,ModeId=Mode,UseInteractiveSetup=true,UseInteractiveDiscard=false,AdvanceAfterHumanCommands=false,MaxTurns=12},r);Accept(g,new StartGameCommand());Reach(g,()=>P(g)is{PlayerSeat:0,Kind:DecisionKind.SelectGeneral});Accept(g,new SelectGeneralCommand(0,Owner,g.Revision,P(g)!.PromptId));try{if(scene=="maximum-zero")Reach(g,()=>P(g)?.SkillPrompt?.SkillId==Death);else if(scene is"qingjiao"or"scarce-zero"or"paid-loss"or"paid-death"or"equipment")Reach(g,()=>Offer(g,Qingjiao));else Play(g);}catch(Exception ex){throw new InvalidOperationException("scene="+scene+"; "+Diagnostic(g),ex);}return(g,r);
    }
