            string Act(string id,string effects,int targets=0,int cards=0,string? filters=null)=>"{\"id\":\""+id+"\",\"minCards\":"+cards+",\"maxCards\":"+cards+",\"minTargets\":"+targets+",\"maxTargets\":"+targets+",\"targetKind\":\""+(targets==1?"anyLiving":"anyLiving")+"\",\"usesPerTurn\":null,"+(filters??"")+"\"effects\":"+effects+"}";
            var acts=new List<string>{Act("deal-one","[{\"op\":\"damage\",\"target\":\"selectedTarget\",\"amount\":1}]",1),Act("deal-two","[{\"op\":\"damage\",\"target\":\"selectedTarget\",\"amount\":2}]",1),Act("self-damage","[{\"op\":\"damage\",\"target\":\"owner\",\"amount\":1}]"),Act("source-less","[{\"op\":\"receiveOwnerDamage\",\"target\":\"owner\",\"amount\":1}]"),Act("dump","[{\"op\":\"discardOwnedZoneCards\",\"target\":\"owner\",\"zones\":[\"hand\"]}]"),Act("draw-four","[{\"op\":\"draw\",\"target\":\"owner\",\"amount\":4}]"),Act("lose-qingjiao","[{\"op\":\"loseOwnerSkillsAndGrant\",\"target\":\"owner\",\"skillIds\":[\"ol:qingjiao\"],\"sourceBind\":\"standard:none\"}]"),Act("place","[{\"op\":\"captureSelectedCards\",\"target\":\"owner\",\"resultBind\":\"gear\"},{\"op\":\"placeSelectedEquipment\",\"target\":\"selectedTarget\",\"sourceBind\":\"gear\"}]",1,1,"\"sourceZones\":[\"hand\"],\"cardCategories\":[\"equipment\"],"),Act("store","[{\"op\":\"captureSelectedCards\",\"target\":\"owner\",\"resultBind\":\"stored\"},{\"op\":\"moveBoundCards\",\"target\":\"owner\",\"sourceBind\":\"stored\",\"destination\":\"ownerPersistentZone\",\"destinationZone\":\"chunlao\",\"awaitMovementTriggers\":true}]",0,1,"\"sourceZones\":[\"hand\"],")};
            foreach(var(id,amount)in new[]{("lose-one",1),("lose-four",4)})acts.Add(Act(id,"[{\"op\":\"loseHp\",\"target\":\"owner\",\"amount\":"+amount+"}]"));
            Skill(Driver,"\"modifiers\":[{\"id\":\"keep\",\"query\":\"handLimit\",\"operation\":\"add\",\"value\":100,\"priority\":0}],\"viewAs\":[{\"id\":\"real-group\",\"inputKinds\":[\"dodge\"],\"inputSuits\":[],\"outputKind\":\"barbarianAssault\",\"forPlay\":true,\"forResponse\":false,\"singleCardTrickUse\":true}],\"activations\":["+string.Join(',',acts)+"]");
            Skill(Quiet,"\"triggers\":[{\"id\":\"quiet\",\"window\":\"afterNormalDraw\",\"subject\":\"owner\",\"optional\":false,\"effects\":[{\"op\":\"skipTurnPhases\",\"target\":\"owner\",\"phases\":[\"play\"]}]}]");
            Skill(Health,"\"triggers\":[{\"id\":\"native-recovery\",\"window\":\"afterHpRecovered\",\"subject\":\"owner\",\"hpChangeOccurrence\":\"perEvent\",\"optional\":false,\"effects\":[{\"op\":\"chooseOption\",\"target\":\"owner\",\"resultBind\":\"health\",\"options\":[{\"id\":\"continue\"}]}]}]");
            var skills=new List<string>{Driver};if(scene is"qingjiao"or"scarce-zero"or"paid-death"or"equipment")skills.Add(Qingjiao);else if(scene=="paid-loss"){Skill(Source,"\"hpSkillGrants\":[{\"id\":\"healthy\",\"skillId\":\"ol:qingjiao\",\"minimumHp\":9}]");skills.Add(Source);}else{skills.Add(Lvli);if(scene is"awaken"or"hand-high"or"maximum-zero"or"foreign-awake")skills.Add(Choujue);}
